109:     /**
110:      * 将 Agent 事件队列转发为 HTTP SSE，并统一处理客户端断开。
111:      *
112:      * @param session 已经启动生产者的 Agent 流会话
113:      * @return 返回给前端的 SSE 响应
114:      */
115:     private SseEmitter createEmitter(AgentStreamSession session) {
116:         // 0L 表示由应用控制何时关闭，避免 Spring 默认超时中断等待确认的流。
117:         SseEmitter emitter = new SseEmitter(0L);
118: 
119:         var terminalDelivered = new java.util.concurrent.atomic.AtomicBoolean(false);
120:         Thread sender = Thread.startVirtualThread(() -> {
121:             try {
122:                 while (!Thread.currentThread().isInterrupted()) {
123:                     // 队列为空时阻塞等待；不会占用 CPU 轮询。
124:                     AgentStreamEvent event = session.queue().take();
125:                     emitter.send(SseEmitter.event()
126:                             .name(event.eventName())
127:                             .data(event.payload()));
128: 
129:                     // done、error、permission_required 都是当前 SSE 的终态事件。
130:                     if (event.isTerminal()) {
131:                         terminalDelivered.set(true);
132:                         return;
133:                     }
134:                 }
135:             } catch (IOException | IllegalStateException exception) {
136:                 // 前端关闭页面或网络断开时，SseEmitter 可能抛出这些异常。
137:                 log.debug("SSE 客户端已断开", exception);
138:             } catch (InterruptedException exception) {
139:                 // onCompletion 会中断 sender；恢复中断标记以便 finally 正常释放资源。
140:                 Thread.currentThread().interrupt();
141:             } finally {
142:                 // 只有非终态断开才取消生产者；正常终态不反向中断 AgentScope。
143:                 if (!terminalDelivered.get()) session.closeTransport();
144:                 emitter.complete();
145:             }
146:         });
147: 
148:         emitter.onCompletion(() -> {
149:             // 浏览器主动断开时，同时停止 SSE 消费线程与 Agent 生产线程。
150:             if (!terminalDelivered.get()) {
151:                 sender.interrupt();
152:                 session.closeTransport();
153:             }
154:         });
155: 
156:         return emitter;
157:     }
158: }

