141:         let base = try APIConfiguration.baseURL()
142:         let server = base.absoluteString.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
143:         guard let current = keychain.getAPISession(server: server) else {
144:             throw APIClientError.unauthenticated
145:         }
146:         let boundary = "Boundary-\(UUID().uuidString)"
147:         var payload = Data()
148:         payload.append(Data("--\(boundary)\r\n".utf8))
149:         payload.append(Data("Content-Disposition: form-data; name=\"\(fieldName)\"; filename=\"\(filename)\"\r\n".utf8))
150:         payload.append(Data("Content-Type: \(mimeType)\r\n\r\n".utf8))
151:         payload.append(fileData)
152:         payload.append(Data("\r\n--\(boundary)--\r\n".utf8))
153: 
154:         let token = current.token.trimmingCharacters(in: .whitespacesAndNewlines)
155:         let response = try await perform(
156:             path, base: base, method: "POST", body: payload,
157:             token: token.isEmpty ? nil : token,
158:             contentType: "multipart/form-data; boundary=\(boundary)"
159:         )
160:         if response.1.statusCode == 401 {
161:             invalidateSession()
162:             throw APIClientError.unauthenticated
163:         }
164:         let data = try accepted(response)
165:         return try Self.decodeResult(T.self, from: data)
166:     }
167: 
168:     static func decodeResult<T: Decodable>(_ type: T.Type, from data: Data) throws -> T {
169:         let envelope = try decoder.decode(APIResultEnvelope<T>.self, from: data)
170:         if envelope.code == 409 { throw APIClientError.conflict }
171:         guard envelope.code == 200 else {
172:             throw APIClientError.server(code: String(envelope.code), status: envelope.code)
173:         }
174:         guard let value = envelope.data else {
175:             throw APIClientError.invalidResponse
176:         }
177:         return value
178:     }
179: 
180:     static var encoder: JSONEncoder { JSONEncoder() }
181: 
182:     static var decoder: JSONDecoder {
183:         let decoder = JSONDecoder()
184:         decoder.dateDecodingStrategy = .custom { decoder in
185:             let container = try decoder.singleValueContainer()
186:             let value = try container.decode(String.self)
187:             let fractional = ISO8601DateFormatter()
188:             fractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
189:             if let date = fractional.date(from: value) { return date }
190:             let regular = ISO8601DateFormatter()
191:             regular.formatOptions = [.withInternetDateTime]
192:             if let date = regular.date(from: value) { return date }
193:             throw APIClientError.invalidResponse
194:         }
195:         return decoder
196:     }
197: 
198:     private func invalidateSession() {
199:         keychain.clearAPISession()
200:         NotificationCenter.default.post(name: .apiSessionExpired, object: nil)
201:     }
202: 
203:     private func perform(
204:         _ path: String, base: URL, method: String, query: [URLQueryItem] = [], body: Data? = nil,
205:         token: String?, idempotencyKey: UUID? = nil, contentType: String = "application/json"
206:     ) async throws -> (Data, HTTPURLResponse) {
207:         guard var components = URLComponents(url: base, resolvingAgainstBaseURL: false)
208:         else { throw APIClientError.invalidServer }
209:         components.path = path
210:         components.queryItems = query.isEmpty ? nil : query
211:         guard let url = components.url else { throw APIClientError.invalidServer }
212:         var request = URLRequest(url: url)
213:         request.httpMethod = method
214:         request.httpBody = body
215:         request.timeoutInterval = 12
216:         request.setValue("*/*", forHTTPHeaderField: "Accept")
217:         if body != nil { request.setValue(contentType, forHTTPHeaderField: "Content-Type") }
218:         if let idempotencyKey {
219:             request.setValue(idempotencyKey.uuidString, forHTTPHeaderField: "Idempotency-Key")
220:         }
221:         if let token { request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization") }
222:         do {
223:             let (data, response) = try await session.data(for: request)
224:             guard let response = response as? HTTPURLResponse else { throw APIClientError.invalidResponse }
225:             return (data, response)
226:         } catch is CancellationError {
227:             throw CancellationError()
228:         } catch let error as URLError where error.code == .cancelled {
229:             throw CancellationError()
230:         } catch let error as APIClientError {
231:             throw error
232:         } catch {
233:             throw APIClientError.network
234:         }
235:     }
236: 
237:     private func accepted(_ result: (Data, HTTPURLResponse)) throws -> Data {
238:         guard !(200..<300).contains(result.1.statusCode) else { return result.0 }
239:         let code = (try? Self.decoder.decode(ServerError.self, from: result.0))?.code ?? ""
240:         switch result.1.statusCode {
241:         case 401: throw APIClientError.unauthenticated
242:         case 409: throw APIClientError.conflict
243:         case 503: throw APIClientError.unavailable
244:         default: throw APIClientError.server(code: code, status: result.1.statusCode)
245:         }
246:     }
247: }

