132:     blocks.push({
133:       id: createBlockId(msg, blocks),
134:       kind: 'tool_group',
135:       tools: [{ toolCallId: targetId, toolName, command, status: 'running' }],
136:     });
137:   }
138:   return { ...msg, tools: nextTools, blocks };
139: }
