23: /**
24:  * 判断一条历史/后端消息是否属于 Agent 主动推送消息。
25:  * 优先认服务端显式 proactive 标记；旧记录缺少该字段时，按“无同轮 USER 消息且无模型耗时/用量”识别。
26:  */
27: export function isProactiveTranscriptMessage(
28:   dto: TranscriptMessageDto,
29:   userTurnIds?: Set<string> | TranscriptMessageDto[],
30: ): boolean {
31:   if (dto.role?.toUpperCase() !== 'ASSISTANT') return false;
32:   if (dto.proactive === true) return true;
33:   if (dto.proactive === false && !userTurnIds) return false;
34:   if (!dto.turnId || dto.status !== 'COMPLETED') return false;
35:   if ((dto.durationMillis ?? 0) !== 0 || dto.usage || dto.thinking) return false;
36:   if (dto.tools && dto.tools.length > 0) return false;
37:   if (dto.blocks && dto.blocks.length > 0) return false;
38:   if (!userTurnIds) return false;
39:   if (userTurnIds instanceof Set) {
40:     return !userTurnIds.has(dto.turnId);
41:   }
42:   return !userTurnIds.some((item) => item.role?.toUpperCase() === 'USER' && item.turnId === dto.turnId);
43: }
