45: function mapToolExecution(tool: TranscriptToolExecutionDto): ToolExecution {
46:   return {
47:     toolCallId: tool.toolCallId,
48:     toolName: tool.toolName,
49:     command: tool.command,
50:     output: tool.output,
51:     status: (tool.status ? tool.status.toLowerCase() : 'completed') as ToolExecution['status'],
52:   };
53: }
