55: function mapTranscriptBlocks(
56:   messageId: string,
57:   dtos?: TranscriptMessageBlockDto[],
58: ): MessageBlock[] | undefined {
59:   if (!dtos || dtos.length === 0) return undefined;
60:   const blocks: MessageBlock[] = [];
61:   dtos.forEach((block, index) => {
62:     if (block.kind === 'THINKING' && block.content?.trim()) {
63:       blocks.push({ id: `${messageId}_b_${index}`, kind: 'thinking', content: block.content });
64:     } else if (block.kind === 'TEXT' && block.content?.trim()) {
65:       blocks.push({ id: `${messageId}_b_${index}`, kind: 'text', content: block.content });
66:     } else if (block.kind === 'TOOL_GROUP' && block.tools && block.tools.length > 0) {
67:       blocks.push({
68:         id: `${messageId}_b_${index}`,
69:         kind: 'tool_group',
70:         tools: block.tools.map(mapToolExecution),
71:       });
72:     }
73:   });
74:   return blocks.length > 0 ? blocks : undefined;
75: }
