77: export function mapTranscriptToChatMessage(
78:   dto: TranscriptMessageDto,
79:   _index?: number,
80:   allMessages?: TranscriptMessageDto[],
81:   userTurnIds?: Set<string>,
82: ): ChatMessage {
83:   const isUser = dto.role?.toUpperCase() === 'USER';
84:   const proactive = isUser ? false : isProactiveTranscriptMessage(dto, userTurnIds ?? allMessages);
85:   const parsedTime = dto.createdAt ? new Date(dto.createdAt).getTime() : NaN;
86:   const createdAt = Number.isFinite(parsedTime) && parsedTime > 0
87:     ? parsedTime
88:     : (proactive ? 0 : Date.now());
89:   return {
90:     id: dto.id,
91:     turnId: dto.turnId,
92:     role: isUser ? 'user' : 'assistant',
93:     modelName: isUser ? undefined : 'ButvanAgent',
94:     content: dto.content || '',
95:     reasoning: dto.thinking || undefined,
96:     createdAt,
97:     status: dto.status,
98:     usage: dto.usage,
99:     proactive: proactive || undefined,
100:     elapsedTime:
101:       dto.durationMillis != null
102:         ? Math.max(1, Math.round(dto.durationMillis / 1000))
103:         : undefined,
104:     tools:
105:       dto.tools && dto.tools.length > 0
106:         ? dto.tools.map(mapToolExecution)
107:         : undefined,
108:     blocks: isUser ? undefined : mapTranscriptBlocks(dto.id, dto.blocks),
109:   };
110: }
