112: /** 批量映射整段会话记录，一次建立用户轮次索引以 O(n) 识别历史主动推送消息。 */
113: export function mapTranscriptMessages(dtos: TranscriptMessageDto[]): ChatMessage[] {
114:   const userTurnIds = new Set<string>();
115:   for (const dto of dtos) {
116:     if (dto.role?.toUpperCase() === 'USER' && dto.turnId) {
117:       userTurnIds.add(dto.turnId);
118:     }
119:   }
120:   return dtos.map((dto, index) => mapTranscriptToChatMessage(dto, index, dtos, userTurnIds));
121: }

