import Foundation

/// 逐字节解析 SSE 事件流，保留空行事件边界与多行 `data:` 换行符。
struct SSELineParser {
    private var lineBuffer: [UInt8] = []
    private var currentEventName: String?
    private var dataLines: [String] = []
    private let decoder: JSONDecoder

    init(decoder: JSONDecoder = APIClient.decoder) {
        self.decoder = decoder
    }

    mutating func feed(_ byte: UInt8) -> AgentStreamEvent? {
        if byte == 0x0A { // '\n'
            if lineBuffer.last == 0x0D { // '\r'
                lineBuffer.removeLast()
            }
            let line = String(decoding: lineBuffer, as: UTF8.self)
            lineBuffer.removeAll(keepingCapacity: true)
            return processLine(line)
        }
        lineBuffer.append(byte)
        return nil
    }

    mutating func finish() -> AgentStreamEvent? {
        if !lineBuffer.isEmpty {
            if lineBuffer.last == 0x0D {
                lineBuffer.removeLast()
            }
            let line = String(decoding: lineBuffer, as: UTF8.self)
            lineBuffer.removeAll(keepingCapacity: false)
            if let event = processLine(line) {
                return event
            }
        }
        return flushEvent()
    }

    private mutating func processLine(_ line: String) -> AgentStreamEvent? {
        if line.isEmpty {
            return flushEvent()
        }
        if line.hasPrefix(":") {
            return nil
        }
        if line.hasPrefix("event:") {
            let value = line.dropFirst(6).trimmingCharacters(in: .whitespaces)
            currentEventName = value.isEmpty ? nil : value
            return nil
        }
        if line.hasPrefix("data:") {
            dataLines.append(String(line.dropFirst(5)))
            return nil
        }
        return nil
    }

    private mutating func flushEvent() -> AgentStreamEvent? {
        guard currentEventName != nil || !dataLines.isEmpty else {
            return nil
        }
        let eventName = currentEventName ?? "message"
        let payload = dataLines.joined(separator: "\n")
        currentEventName = nil
        dataLines.removeAll(keepingCapacity: true)
        return decodeEvent(name: eventName, dataString: payload)
    }

    private func decodeEvent(name: String, dataString: String) -> AgentStreamEvent? {
        switch name {
        case "run_started":
            if let dto = decodeJSON(RunStartedDTO.self, from: dataString) {
                return .runStarted(runId: dto.runId ?? "")
            }
            return nil

        case "text", "message":
            return dataString.isEmpty ? nil : .text(dataString)

        case "thinking":
            return dataString.isEmpty ? nil : .thinking(dataString)

        case "tool_call":
            if let dto = decodeJSON(ToolCallDTO.self, from: dataString) {
                return .toolCall(
                    toolCallId: dto.toolCallId ?? "",
                    toolName: dto.toolName ?? "tool",
                    command: dto.command ?? ""
                )
            }
            return .toolCall(toolCallId: "", toolName: "tool", command: dataString)

        case "tool_result":
            if let dto = decodeJSON(ToolResultDTO.self, from: dataString) {
                return .toolResult(
                    toolCallId: dto.toolCallId ?? "",
                    toolName: dto.toolName ?? "tool",
                    result: dto.result ?? "",
                    status: dto.status ?? .completed
                )
            }
            return .toolResult(toolCallId: "", toolName: "tool", result: dataString, status: .completed)

        case "permission_required":
            if let approval = decodeJSON(AgentPendingApproval.self, from: dataString) {
                return .permissionRequired(approval)
            }
            return .error(String(localized: "agent.error.invalid_permission_event"))

        case "subagent":
            if let progress = decodeJSON(AgentSubagentProgress.self, from: dataString) {
                return .subagent(progress)
            }
            return nil

        case "routing_notice":
            if let notice = decodeJSON(AgentRoutingNotice.self, from: dataString) {
                return .routingNotice(notice)
            }
            return nil

        case "cancelled":
            let dto = decodeJSON(CancelledDTO.self, from: dataString)
            return .cancelled(runId: dto?.runId)

        case "error":
            let trimmed = dataString.trimmingCharacters(in: .whitespacesAndNewlines)
            return .error(trimmed.isEmpty ? String(localized: "agent.error.stream_failed") : trimmed)

        case "done":
            return .done

        default:
            return nil
        }
    }

    private func decodeJSON<T: Decodable>(_ type: T.Type, from raw: String) -> T? {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let data = trimmed.data(using: .utf8) else {
            return nil
        }
        return try? decoder.decode(type, from: data)
    }
}

private struct RunStartedDTO: Decodable {
    let runId: String?
}

private struct ToolCallDTO: Decodable {
    let toolCallId: String?
    let toolName: String?
    let command: String?
}

private struct ToolResultDTO: Decodable {
    let toolCallId: String?
    let toolName: String?
    let result: String?
    let status: AgentToolStatus?
}

private struct CancelledDTO: Decodable {
    let runId: String?
}

import Foundation

/// 直连 `agent-backend/` 的 Agent 对话、会话管理、审批与模型配置服务。
final class APIAgentService: AgentServiceProtocol, @unchecked Sendable {
    private let client: APIClient

    init(client: APIClient) {
        self.client = client
    }

    func listSessions() async throws -> [AgentSessionSummary] {
        try await client.sendResult("/agent/sessions")
    }

    func listFeishuSessions() async throws -> [AgentSessionSummary] {
        try await client.sendResult("/agent/sessions/feishu")
    }

    func getSessionDetail(sessionId: String) async throws -> AgentSessionDetailDTO {
        let escaped = Self.escapePathComponent(sessionId)
        return try await client.sendResult("/agent/sessions/\(escaped)")
    }

    func getFeishuSessionDetail(sessionId: String) async throws -> AgentSessionDetailDTO {
        let escaped = Self.escapePathComponent(sessionId)
        return try await client.sendResult("/agent/sessions/feishu/\(escaped)")
    }

    func createSession(
        kind: AgentSessionKind,
        title: String,
        projectId: String?
    ) async throws -> AgentSessionSummary {
        let body = try APIClient.encoder.encode(CreateSessionPayload(
            kind: kind,
            title: title,
            projectId: projectId
        ))
        return try await client.sendResult("/agent/sessions", method: "POST", body: body)
    }

    func updateSessionTitle(sessionId: String, title: String) async throws -> AgentSessionSummary {
        let escaped = Self.escapePathComponent(sessionId)
        let body = try APIClient.encoder.encode(UpdateSessionTitlePayload(title: title))
        return try await client.sendResult("/agent/sessions/\(escaped)", method: "PATCH", body: body)
    }

    func generateSessionTitle(sessionId: String) async throws -> AgentSessionSummary? {
        let escaped = Self.escapePathComponent(sessionId)
        return try await client.sendOptionalResult("/agent/sessions/\(escaped)/title/generate", method: "POST")
    }

    func deleteSession(sessionId: String) async throws {
        let escaped = Self.escapePathComponent(sessionId)
        let _: EmptyPayload? = try await client.sendOptionalResult("/agent/sessions/\(escaped)", method: "DELETE")
    }

    func getPermissionMode(sessionId: String) async throws -> AgentSessionPermissionMode {
        let escaped = Self.escapePathComponent(sessionId)
        let response: PermissionModePayload = try await client.sendResult(
            "/agent/sessions/\(escaped)/permission-mode"
        )
        return response.mode
    }

    func updatePermissionMode(
        sessionId: String,
        mode: AgentSessionPermissionMode
    ) async throws -> AgentSessionPermissionMode {
        let escaped = Self.escapePathComponent(sessionId)
        let body = try APIClient.encoder.encode(PermissionModePayload(mode: mode))
        let response: PermissionModePayload = try await client.sendResult(
            "/agent/sessions/\(escaped)/permission-mode",
            method: "PUT",
            body: body
        )
        return response.mode
    }

    func fetchPendingPermission(sessionId: String) async throws -> AgentPendingApproval? {
        let escaped = Self.escapePathComponent(sessionId)
        guard let data = try await client.sendRawAllowingEmpty(
            "/agent/chat/\(escaped)/permission/pending",
            emptyStatusCodes: [204]
        ) else {
            return nil
        }
        return try APIClient.decoder.decode(AgentPendingApproval.self, from: data)
    }

    func submitPermissionDecisions(
        sessionId: String,
        approvalId: String,
        decisions: [AgentPermissionDecisionInput]
    ) async throws -> AgentPermissionDecisionResponse {
        let body = try APIClient.encoder.encode(PermissionBatchDecisionPayload(
            sessionId: sessionId,
            approvalId: approvalId,
            decisions: decisions
        ))
        guard let data = try await client.sendRawAllowingEmpty(
            "/agent/chat/permission/decisions",
            method: "POST",
            body: body,
            emptyStatusCodes: []
        ) else {
            throw APIClientError.invalidResponse
        }
        return try APIClient.decoder.decode(AgentPermissionDecisionResponse.self, from: data)
    }

    func cancelRun(sessionId: String, runId: String) async throws -> AgentRunCancelResponse {
        let escapedRunId = Self.escapePathComponent(runId)
        let body = try APIClient.encoder.encode(RunCancelPayload(sessionId: sessionId))
        guard let data = try await client.sendRawAllowingEmpty(
            "/agent/chat/runs/\(escapedRunId)/cancel",
            method: "POST",
            body: body,
            emptyStatusCodes: []
        ) else {
            throw APIClientError.invalidResponse
        }
        return try APIClient.decoder.decode(AgentRunCancelResponse.self, from: data)
    }

    func fetchPlan(sessionId: String) async throws -> String? {
        let escaped = Self.escapePathComponent(sessionId)
        guard let data = try await client.sendRawAllowingEmpty(
            "/agent/chat/\(escaped)/plan",
            emptyStatusCodes: [204, 404]
        ) else {
            return nil
        }
        let payload = try APIClient.decoder.decode(PlanPayload.self, from: data)
        let trimmed = payload.content?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : payload.content
    }

    func streamChat(
        runId: String,
        sessionId: String,
        content: String,
        recordReferenceIds: [String]
    ) -> AsyncThrowingStream<AgentStreamEvent, Error> {
        let payload = StreamChatPayload(
            runId: runId,
            sessionId: sessionId,
            content: content,
            context: content,
            recordReferenceIds: recordReferenceIds
        )
        return openEventStream(path: "/agent/chat/stream", payload: payload)
    }

    func resumeChat(
        sessionId: String,
        approvalId: String,
        runId: String
    ) -> AsyncThrowingStream<AgentStreamEvent, Error> {
        let payload = ResumeChatPayload(
            sessionId: sessionId,
            approvalId: approvalId,
            runId: runId
        )
        return openEventStream(path: "/agent/chat/permission/resume", payload: payload)
    }

    func fetchModelConfig() async throws -> AgentModelConfig {
        try await client.sendResult("/agent/model/config")
    }

    func fetchFullModelConfig() async throws -> AgentFullModelConfig {
        try await client.sendResult("/agent/model/full-config")
    }

    func switchModel(
        vendor: String,
        modelName: String,
        apiKey: String,
        baseUrl: String?,
        protocolName: String?
    ) async throws {
        let body = try APIClient.encoder.encode(SetModelPayload(
            modelName: modelName,
            vendor: vendor,
            apiKey: apiKey,
            baseUrl: baseUrl,
            protocol: protocolName
        ))
        let _: String? = try await client.sendOptionalResult("/agent/model", method: "POST", body: body)
    }

    private func openEventStream<Body: Encodable & Sendable>(
        path: String,
        payload: Body
    ) -> AsyncThrowingStream<AgentStreamEvent, Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    let body = try APIClient.encoder.encode(payload)
                    let bytes = try await client.openStreamBytes(path, method: "POST", body: body)
                    var parser = SSELineParser()
                    var reachedTerminal = false

                    for try await byte in bytes {
                        try Task.checkCancellation()
                        if let event = parser.feed(byte) {
                            continuation.yield(event)
                            if Self.isTerminal(event) {
                                reachedTerminal = true
                                break
                            }
                        }
                    }

                    if !reachedTerminal, let trailing = parser.finish() {
                        continuation.yield(trailing)
                        if Self.isTerminal(trailing) {
                            reachedTerminal = true
                        }
                    }

                    if !reachedTerminal {
                        continuation.yield(.error(String(localized: "agent.error.unexpected_eof")))
                    }
                    continuation.finish()
                } catch is CancellationError {
                    continuation.finish(throwing: CancellationError())
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in
                task.cancel()
            }
        }
    }

    private static func isTerminal(_ event: AgentStreamEvent) -> Bool {
        switch event {
        case .done, .cancelled, .error, .permissionRequired:
            return true
        case .runStarted, .text, .thinking, .toolCall, .toolResult, .subagent, .routingNotice:
            return false
        }
    }

    private static func escapePathComponent(_ value: String) -> String {
        value.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? value
    }
}

private struct CreateSessionPayload: Encodable {
    let kind: AgentSessionKind
    let title: String
    let projectId: String?
}

private struct UpdateSessionTitlePayload: Encodable {
    let title: String
}

private struct PermissionModePayload: Codable {
    let mode: AgentSessionPermissionMode
}

private struct PermissionBatchDecisionPayload: Encodable {
    let sessionId: String
    let approvalId: String
    let decisions: [AgentPermissionDecisionInput]
}

private struct RunCancelPayload: Encodable {
    let sessionId: String
}

private struct PlanPayload: Decodable {
    let content: String?
}

private struct StreamChatPayload: Encodable {
    let runId: String
    let sessionId: String
    let content: String
    let context: String
    let recordReferenceIds: [String]
}

private struct ResumeChatPayload: Encodable {
    let sessionId: String
    let approvalId: String
    let runId: String
}

private struct SetModelPayload: Encodable {
    let modelName: String
    let vendor: String
    let apiKey: String
    let baseUrl: String?
    let `protocol`: String?
}

private struct EmptyPayload: Decodable {}

import Foundation
import SwiftUI

/// 管理 Agent 对话流、会话切换、权限审批与模型配置的视图模型。
@MainActor
final class AgentChatViewModel: ObservableObject {
    @Published private(set) var sessions: [AgentSessionSummary] = []
    @Published private(set) var feishuSessions: [AgentSessionSummary] = []
    @Published private(set) var activeSessionId: String?
    @Published private(set) var activeSessionIsReadOnly = false
    @Published private(set) var messages: [AgentChatMessage] = []
    @Published private(set) var permissionMode: AgentSessionPermissionMode = .ask
    @Published private(set) var pendingApproval: AgentPendingApproval?
    @Published var approvalSelections: [String: AgentPermissionDecisionInput] = [:]

    @Published private(set) var isStreaming = false
    @Published private(set) var isStopping = false
    @Published private(set) var isSubmittingApproval = false
    @Published private(set) var streamingRunId: String?
    @Published private(set) var elapsedSeconds = 0
    @Published var draftText = ""

    @Published private(set) var modelConfig: AgentModelConfig?
    @Published private(set) var fullModelConfig: AgentFullModelConfig?
    @Published private(set) var isSwitchingModel = false
    @Published private(set) var activePlanContent: String?
    @Published private(set) var routingNotice: AgentRoutingNotice?
    @Published private(set) var subagentNotices: [AgentSubagentProgress] = []

    @Published private(set) var isLoadingInitial = false
    @Published private(set) var isLoadingSessions = false
    @Published private(set) var isLoadingMessages = false
    @Published var errorMessage: String?

    private let service: any AgentServiceProtocol
    private var hasLoadedOnce = false
    private var loadGeneration = 0
    private var streamTask: Task<Void, Never>?
    private var timerTask: Task<Void, Never>?

    init(service: any AgentServiceProtocol) {
        self.service = service
    }

    var activeSession: AgentSessionSummary? {
        guard let activeSessionId else { return nil }
        if activeSessionIsReadOnly {
            return feishuSessions.first { $0.id == activeSessionId }
        }
        return sessions.first { $0.id == activeSessionId }
    }

    var currentModelDisplayName: String {
        if let name = modelConfig?.displayName, !name.isEmpty {
            return name
        }
        if let active = fullModelConfig?.activeModel, !active.isEmpty {
            return active
        }
        return String(localized: "agent.model.unset")
    }

    var canSend: Bool {
        !activeSessionIsReadOnly
            && !isStreaming
            && pendingApproval == nil
            && !draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    func loadInitialIfNeeded() async {
        guard !hasLoadedOnce else { return }
        hasLoadedOnce = true
        isLoadingInitial = true
        defer { isLoadingInitial = false }

        async let loadedSessions = loadSessionsInternal()
        async let loadedModels = refreshModelState()
        _ = await (loadedSessions, loadedModels)

        if activeSessionId == nil, let latest = sessions.first {
            await selectSession(latest, readOnly: false)
        }
    }

    func refreshAll() async {
        await loadSessionsInternal()
        await refreshModelState()
        if let activeSessionId {
            await reloadSessionDetail(sessionId: activeSessionId, readOnly: activeSessionIsReadOnly)
        }
    }

    func refreshSessions() async {
        await loadSessionsInternal()
    }

    func refreshModelState() async {
        do {
            async let config = service.fetchModelConfig()
            async let full = service.fetchFullModelConfig()
            let (resolvedConfig, resolvedFull) = try await (config, full)
            modelConfig = resolvedConfig
            fullModelConfig = resolvedFull
        } catch {
            // 仅静默降级展示，不阻断对话主流程。
            if let fallback = try? await service.fetchModelConfig() {
                modelConfig = fallback
            }
        }
    }

    func startNewChat() {
        cancelActiveStreamLocally()
        loadGeneration += 1
        activeSessionId = nil
        activeSessionIsReadOnly = false
        messages = []
        pendingApproval = nil
        approvalSelections = [:]
        activePlanContent = nil
        routingNotice = nil
        subagentNotices = []
        errorMessage = nil
        permissionMode = .ask
    }

    func selectSession(_ summary: AgentSessionSummary, readOnly: Bool) async {
        cancelActiveStreamLocally()
        activeSessionId = summary.id
        activeSessionIsReadOnly = readOnly
        pendingApproval = nil
        approvalSelections = [:]
        activePlanContent = nil
        routingNotice = nil
        subagentNotices = []
        errorMessage = nil
        await reloadSessionDetail(sessionId: summary.id, readOnly: readOnly)
    }

    func sendPrompt(_ text: String) async {
        draftText = text
        await sendCurrentDraft()
    }

    func sendCurrentDraft() async {
        let trimmed = draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !activeSessionIsReadOnly, !isStreaming, pendingApproval == nil else {
            return
        }

        errorMessage = nil
        routingNotice = nil
        subagentNotices = []
        let outgoing = trimmed
        draftText = ""

        let targetSessionId: String
        let wasEmptySession: Bool
        if let existingId = activeSessionId {
            targetSessionId = existingId
            wasEmptySession = messages.isEmpty
        } else {
            do {
                let defaultTitle = String(localized: "agent.session.default_title")
                let created = try await service.createSession(kind: .general, title: defaultTitle, projectId: nil)
                sessions.insert(created, at: 0)
                activeSessionId = created.id
                activeSessionIsReadOnly = false
                targetSessionId = created.id
                wasEmptySession = true
            } catch {
                draftText = outgoing
                errorMessage = Self.userFacingError(error)
                return
            }
        }

        let userMessage = AgentChatMessage(
            id: "local_user_\(UUID().uuidString)",
            turnId: nil,
            role: .user,
            content: outgoing,
            thinking: nil,
            createdAt: Date(),
            status: .completed,
            durationSeconds: nil,
            tools: [],
            blocks: [],
            proactive: false,
            usage: nil,
            isStreaming: false
        )
        let assistantId = "local_assistant_\(UUID().uuidString)"
        let assistantMessage = AgentChatMessage(
            id: assistantId,
            turnId: nil,
            role: .assistant,
            content: "",
            thinking: nil,
            createdAt: Date(),
            status: nil,
            durationSeconds: nil,
            tools: [],
            blocks: [],
            proactive: false,
            usage: nil,
            isStreaming: true
        )
        messages.append(userMessage)
        messages.append(assistantMessage)

        let runId = UUID().uuidString.lowercased()
        let stream = service.streamChat(
            runId: runId,
            sessionId: targetSessionId,
            content: outgoing,
            recordReferenceIds: []
        )
        startStreamConsumption(
            stream,
            sessionId: targetSessionId,
            assistantMessageId: assistantId,
            initialRunId: runId,
            shouldGenerateTitle: wasEmptySession
        )
    }

    func stopStreaming() async {
        guard isStreaming, let sessionId = activeSessionId, let runId = streamingRunId else { return }
        isStopping = true
        do {
            _ = try await service.cancelRun(sessionId: sessionId, runId: runId)
        } catch {
            // 若后端停止请求失败，中止本地消费并回读权威会话状态。
            cancelActiveStreamLocally()
            errorMessage = Self.userFacingError(error)
            await reloadSessionDetail(sessionId: sessionId, readOnly: false)
        }
    }

    func setApproval(toolCallId: String, approved: Bool, rememberForSession: Bool? = nil) {
        let existing = approvalSelections[toolCallId]
        approvalSelections[toolCallId] = AgentPermissionDecisionInput(
            toolCallId: toolCallId,
            approved: approved,
            rememberForSession: rememberForSession ?? existing?.rememberForSession ?? false
        )
    }

    func submitApprovalDecisions(overrideAllApproved: Bool? = nil) async {
        guard let approval = pendingApproval,
              let sessionId = activeSessionId,
              !isSubmittingApproval else {
            return
        }

        let decisions: [AgentPermissionDecisionInput] = approval.tools.map { tool in
            let current = approvalSelections[tool.toolCallId]
            return AgentPermissionDecisionInput(
                toolCallId: tool.toolCallId,
                approved: overrideAllApproved ?? current?.approved ?? true,
                rememberForSession: current?.rememberForSession ?? false
            )
        }

        isSubmittingApproval = true
        errorMessage = nil
        defer { isSubmittingApproval = false }

        do {
            let response = try await service.submitPermissionDecisions(
                sessionId: sessionId,
                approvalId: approval.approvalId,
                decisions: decisions
            )
            pendingApproval = nil
            approvalSelections = [:]

            if response.readyToResume {
                let targetId = ensureStreamingAssistantMessage(
                    partialContent: approval.partialContent
                )
                let stream = service.resumeChat(
                    sessionId: sessionId,
                    approvalId: approval.approvalId,
                    runId: approval.runId
                )
                startStreamConsumption(
                    stream,
                    sessionId: sessionId,
                    assistantMessageId: targetId,
                    initialRunId: approval.runId,
                    shouldGenerateTitle: false
                )
            }
        } catch {
            errorMessage = Self.userFacingError(error)
        }
    }

    func renameSession(_ summary: AgentSessionSummary, newTitle: String) async {
        let trimmed = newTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        do {
            let updated = try await service.updateSessionTitle(sessionId: summary.id, title: trimmed)
            if let idx = sessions.firstIndex(where: { $0.id == updated.id }) {
                sessions[idx] = updated
            }
        } catch {
            errorMessage = Self.userFacingError(error)
        }
    }

    func deleteSession(_ summary: AgentSessionSummary) async {
        do {
            try await service.deleteSession(sessionId: summary.id)
            sessions.removeAll { $0.id == summary.id }
            if activeSessionId == summary.id {
                startNewChat()
                if let next = sessions.first {
                    await selectSession(next, readOnly: false)
                }
            }
        } catch {
            errorMessage = Self.userFacingError(error)
        }
    }

    func updatePermissionMode(_ mode: AgentSessionPermissionMode) async {
        guard let sessionId = activeSessionId, !activeSessionIsReadOnly else {
            permissionMode = mode
            return
        }
        let previous = permissionMode
        permissionMode = mode
        do {
            permissionMode = try await service.updatePermissionMode(sessionId: sessionId, mode: mode)
        } catch {
            permissionMode = previous
            errorMessage = Self.userFacingError(error)
        }
    }

    func loadPlan() async {
        guard let sessionId = activeSessionId else { return }
        do {
            activePlanContent = try await service.fetchPlan(sessionId: sessionId)
        } catch {
            errorMessage = Self.userFacingError(error)
        }
    }

    func switchModel(provider: AgentProviderConfig, item: AgentModelItem) async -> Bool {
        guard !isSwitchingModel else { return false }
        isSwitchingModel = true
        errorMessage = nil
        defer { isSwitchingModel = false }

        do {
            try await service.switchModel(
                vendor: provider.type,
                modelName: item.modelName,
                apiKey: provider.apiKey ?? "",
                baseUrl: provider.baseUrl?.isEmpty == false ? provider.baseUrl : nil,
                protocolName: provider.protocol?.isEmpty == false ? provider.protocol : nil
            )
            await refreshModelState()
            return true
        } catch {
            errorMessage = Self.userFacingError(error)
            return false
        }
    }

    // MARK: - 内部流式消费与状态同步

    private func loadSessionsInternal() async {
        isLoadingSessions = true
        defer { isLoadingSessions = false }
        do {
            async let mainList = service.listSessions()
            async let feishuList = service.listFeishuSessions()
            let (resolvedMain, resolvedFeishu) = try await (mainList, feishuList)
            sessions = resolvedMain.sorted { $0.updatedAt > $1.updatedAt }
            feishuSessions = resolvedFeishu.sorted { $0.updatedAt > $1.updatedAt }
        } catch {
            errorMessage = Self.userFacingError(error)
        }
    }

    private func reloadSessionDetail(sessionId: String, readOnly: Bool) async {
        loadGeneration += 1
        let expectedGen = loadGeneration
        isLoadingMessages = true
        defer {
            if loadGeneration == expectedGen {
                isLoadingMessages = false
            }
        }

        do {
            let detail: AgentSessionDetailDTO
            if readOnly {
                detail = try await service.getFeishuSessionDetail(sessionId: sessionId)
            } else {
                detail = try await service.getSessionDetail(sessionId: sessionId)
            }
            guard loadGeneration == expectedGen, activeSessionId == sessionId else { return }

            messages = AgentTimelineBuilder.mapTranscriptMessages(detail.messages)
            if !readOnly {
                if let idx = sessions.firstIndex(where: { $0.id == detail.summary.id }) {
                    sessions[idx] = detail.summary
                }
                async let mode = try? service.getPermissionMode(sessionId: sessionId)
                async let pending = try? service.fetchPendingPermission(sessionId: sessionId)
                async let plan = try? service.fetchPlan(sessionId: sessionId)
                let (resolvedMode, resolvedPending, resolvedPlan) = await (mode, pending, plan)
                guard loadGeneration == expectedGen, activeSessionId == sessionId else { return }
                if let resolvedMode { permissionMode = resolvedMode }
                if let resolvedPending {
                    setPendingApproval(resolvedPending)
                }
                activePlanContent = resolvedPlan
            }
        } catch {
            guard loadGeneration == expectedGen else { return }
            errorMessage = Self.userFacingError(error)
        }
    }

    private func startStreamConsumption(
        _ stream: AsyncThrowingStream<AgentStreamEvent, Error>,
        sessionId: String,
        assistantMessageId: String,
        initialRunId: String,
        shouldGenerateTitle: Bool
    ) {
        cancelActiveStreamLocally()
        isStreaming = true
        isStopping = false
        streamingRunId = initialRunId
        elapsedSeconds = 0

        timerTask = Task { [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(1))
                guard !Task.isCancelled, let self else { return }
                self.elapsedSeconds += 1
            }
        }

        streamTask = Task { [weak self] in
            guard let self else { return }
            var terminatedExplicitly = false
            do {
                for try await event in stream {
                    guard !Task.isCancelled else { return }
                    switch event {
                    case .runStarted(let serverRunId):
                        if !serverRunId.isEmpty {
                            self.streamingRunId = serverRunId
                        }

                    case .thinking(let chunk):
                        self.mutateMessage(id: assistantMessageId) {
                            AgentTimelineBuilder.appendThinking($0, chunk: chunk)
                        }

                    case .text(let chunk):
                        self.mutateMessage(id: assistantMessageId) {
                            AgentTimelineBuilder.appendText($0, chunk: chunk)
                        }

                    case .toolCall(let toolCallId, let toolName, let command):
                        self.mutateMessage(id: assistantMessageId) {
                            AgentTimelineBuilder.upsertToolCall(
                                $0,
                                toolCallId: toolCallId,
                                toolName: toolName,
                                command: command
                            )
                        }

                    case .toolResult(let toolCallId, _, let result, let status):
                        self.mutateMessage(id: assistantMessageId) {
                            AgentTimelineBuilder.applyToolResult(
                                $0,
                                toolCallId: toolCallId,
                                result: result,
                                status: status
                            )
                        }

                    case .routingNotice(let notice):
                        self.routingNotice = notice

                    case .subagent(let progress):
                        self.upsertSubagentNotice(progress)

                    case .permissionRequired(let approval):
                        terminatedExplicitly = true
                        self.finishStreamingFlags(
                            assistantMessageId: assistantMessageId,
                            status: nil
                        )
                        self.setPendingApproval(approval)

                    case .done:
                        terminatedExplicitly = true
                        self.finishStreamingFlags(
                            assistantMessageId: assistantMessageId,
                            status: .completed
                        )
                        await self.syncSessionAfterStream(
                            sessionId: sessionId,
                            shouldGenerateTitle: shouldGenerateTitle
                        )

                    case .cancelled:
                        terminatedExplicitly = true
                        self.finishStreamingFlags(
                            assistantMessageId: assistantMessageId,
                            status: .cancelled
                        )
                        await self.syncSessionAfterStream(
                            sessionId: sessionId,
                            shouldGenerateTitle: false
                        )

                    case .error(let message):
                        terminatedExplicitly = true
                        self.finishStreamingFlags(
                            assistantMessageId: assistantMessageId,
                            status: .failed
                        )
                        self.errorMessage = message
                    }
                }
                if !terminatedExplicitly {
                    self.finishStreamingFlags(
                        assistantMessageId: assistantMessageId,
                        status: .completed
                    )
                }
            } catch is CancellationError {
                self.finishStreamingFlags(assistantMessageId: assistantMessageId, status: .cancelled)
            } catch {
                self.finishStreamingFlags(assistantMessageId: assistantMessageId, status: .failed)
                self.errorMessage = Self.userFacingError(error)
            }
        }
    }

    private func syncSessionAfterStream(sessionId: String, shouldGenerateTitle: Bool) async {
        if let detail = try? await service.getSessionDetail(sessionId: sessionId) {
            if let idx = sessions.firstIndex(where: { $0.id == detail.summary.id }) {
                sessions[idx] = detail.summary
            }
            if activeSessionId == sessionId {
                messages = AgentTimelineBuilder.mapTranscriptMessages(detail.messages)
            }
        }
        if shouldGenerateTitle, let generated = try? await service.generateSessionTitle(sessionId: sessionId) {
            if let idx = sessions.firstIndex(where: { $0.id == generated.id }) {
                sessions[idx] = generated
            }
        }
        if let plan = try? await service.fetchPlan(sessionId: sessionId), activeSessionId == sessionId {
            activePlanContent = plan
        }
        sessions.sort { $0.updatedAt > $1.updatedAt }
    }

    private func finishStreamingFlags(
        assistantMessageId: String,
        status: AgentMessageStatus?
    ) {
        timerTask?.cancel()
        timerTask = nil
        let elapsed = elapsedSeconds
        isStreaming = false
        isStopping = false
        streamingRunId = nil
        mutateMessage(id: assistantMessageId) { msg in
            var copy = msg
            copy.isStreaming = false
            if let status {
                copy.status = status
            }
            if copy.durationSeconds == nil, elapsed > 0 {
                copy.durationSeconds = elapsed
            }
            return copy
        }
    }

    private func cancelActiveStreamLocally() {
        streamTask?.cancel()
        streamTask = nil
        timerTask?.cancel()
        timerTask = nil
        isStreaming = false
        isStopping = false
        streamingRunId = nil
    }

    private func ensureStreamingAssistantMessage(partialContent: String?) -> String {
        if let last = messages.last, last.role == .assistant, last.status == nil {
            mutateMessage(id: last.id) { msg in
                var copy = msg
                copy.isStreaming = true
                return copy
            }
            return last.id
        }
        let id = "local_resume_\(UUID().uuidString)"
        var message = AgentChatMessage(
            id: id,
            turnId: nil,
            role: .assistant,
            content: "",
            thinking: nil,
            createdAt: Date(),
            status: nil,
            durationSeconds: nil,
            tools: [],
            blocks: [],
            proactive: false,
            usage: nil,
            isStreaming: true
        )
        if let partialContent, !partialContent.isEmpty {
            message = AgentTimelineBuilder.appendText(message, chunk: partialContent)
        }
        messages.append(message)
        return id
    }

    private func setPendingApproval(_ approval: AgentPendingApproval) {
        pendingApproval = approval
        var initial: [String: AgentPermissionDecisionInput] = [:]
        for tool in approval.tools {
            initial[tool.toolCallId] = AgentPermissionDecisionInput(
                toolCallId: tool.toolCallId,
                approved: true,
                rememberForSession: false
            )
        }
        approvalSelections = initial
    }

    private func mutateMessage(id: String, transform: (AgentChatMessage) -> AgentChatMessage) {
        guard let idx = messages.firstIndex(where: { $0.id == id }) else { return }
        messages[idx] = transform(messages[idx])
    }

    private func upsertSubagentNotice(_ progress: AgentSubagentProgress) {
        if let idx = subagentNotices.firstIndex(where: { $0.source == progress.source }) {
            subagentNotices[idx] = progress
        } else {
            subagentNotices.append(progress)
        }
    }

    private static func userFacingError(_ error: Error) -> String {
        if let apiError = error as? APIClientError, let desc = apiError.errorDescription {
            return desc
        }
        return error.localizedDescription
    }
}

import SwiftUI

/// 轻量极简 Markdown 视图：直排正文与标题列表，代码块使用柔和无边框底色与复制按钮。
struct AgentMarkdownView: View {
    let text: String

    private var segments: [MarkdownSegment] {
        MarkdownSegment.parse(text)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            ForEach(segments) { segment in
                switch segment.kind {
                case .prose(let content):
                    AgentProseBlockView(content: content)
                case .code(let language, let code):
                    AgentCodeBlockView(language: language, code: code)
                }
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .textSelection(.enabled)
    }
}

private struct AgentProseBlockView: View {
    let content: String

    var body: some View {
        let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
        VStack(alignment: .leading, spacing: 6) {
            ForEach(Array(lines.enumerated()), id: \.offset) { _, line in
                proseLine(line)
            }
        }
    }

    @ViewBuilder
    private func proseLine(_ raw: String) -> some View {
        let trimmed = raw.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty {
            Spacer().frame(height: 2)
        } else if trimmed.hasPrefix("### ") {
            inlineText(String(trimmed.dropFirst(4)))
                .font(.headline)
                .padding(.top, 4)
        } else if trimmed.hasPrefix("## ") {
            inlineText(String(trimmed.dropFirst(3)))
                .font(.title3.weight(.semibold))
                .padding(.top, 6)
        } else if trimmed.hasPrefix("# ") {
            inlineText(String(trimmed.dropFirst(2)))
                .font(.title2.weight(.bold))
                .padding(.top, 6)
        } else if trimmed.hasPrefix("- ") || trimmed.hasPrefix("* ") {
            HStack(alignment: .top, spacing: 8) {
                Text("•")
                    .foregroundStyle(.secondary)
                inlineText(String(trimmed.dropFirst(2)))
            }
            .padding(.leading, 4)
        } else {
            inlineText(raw)
        }
    }

    private func inlineText(_ source: String) -> Text {
        if let attributed = try? AttributedString(
            markdown: source,
            options: .init(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        ) {
            return Text(attributed)
        }
        return Text(verbatim: source)
    }
}

private struct AgentCodeBlockView: View {
    let language: String
    let code: String
    @State private var copied = false

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
